/**
 * question-bank/index.ts — 诊断问题库
 *
 * 为诊断 Phase 0（界定）+ Phase 1（采集）提供结构化问卷。
 *
 * 设计：
 *   - ~150 道种子题，按 [维度] × [角色类型] × [阶段] 三维索引
 *   - addCustomQuestion() 扩展 API（供 FDE 手动添加）
 *   - 检索：按维度/角色/阶段/关键词多条件过滤
 *   - 每个问题带 source 标记（builtin / custom），用于反馈循环
 *
 * 问题类型：
 *   - scale_1_10    — 1-10 打分题
 *   - multiple_choice — 单选题
 *   - open_ended    — 开放题
 *   - scenario      — 场景判断题
 */
export type QuestionType = 'scale_1_10' | 'multiple_choice' | 'open_ended' | 'scenario';
export type DiagnosticPhase = 0 | 1;
/** 适用角色 */
export type TargetRole = 'any' | 'founder' | 'executive' | 'engineering-manager' | 'product-manager' | 'senior-engineer' | 'junior-engineer' | 'designer' | 'data-scientist' | 'devops' | 'hr' | 'operations' | 'sales' | 'marketing';
/** 适用维度 */
export type TargetDimension = '信任与心理安全' | '决策权分配' | '信息透明度' | '分工合理性' | '目标对齐' | '角色清晰度' | '冲突解决模式' | '工具与自动化' | '品类认知与定位' | '获客与转化' | '客户关系与品牌' | '服务体验' | 'any';
export interface QuestionChoice {
    value: string;
    label: string;
    /** 该选项暗示的问题等级（1-10） */
    scoreHint?: number;
}
export interface DiagnosticQuestion {
    id: string;
    type: QuestionType;
    /** 所属诊断阶段 */
    phase: DiagnosticPhase;
    /** 问题文本 */
    text: string;
    /** 适用维度 */
    dimension: TargetDimension;
    /** 适用角色 */
    targetRole: TargetRole;
    /** 选择题的选项（仅 multiple_choice） */
    choices?: QuestionChoice[];
    /** 开放题的追问提示 */
    followUp?: string;
    /** 来源——builtin 或 custom */
    source: 'builtin' | 'custom';
    /** 该问题的默认权重 0-1（在证据池中的重要性） */
    weight: number;
    /** 创建时间（custom 问题用） */
    createdAt?: string;
}
export interface QuestionFilter {
    phase?: DiagnosticPhase;
    dimension?: TargetDimension;
    targetRole?: TargetRole;
    type?: QuestionType;
    keyword?: string;
    /** 只返回指定来源的问题 */
    source?: 'builtin' | 'custom';
}
/** 检索问题 */
export declare function queryQuestions(filter?: QuestionFilter): DiagnosticQuestion[];
/** 按维度分组统计 */
export declare function countByDimension(): Record<string, number>;
/** 按角色分组统计 */
export declare function countByRole(): Record<string, number>;
/** 添加自定义问题（FDE 扩展 API） */
export declare function addCustomQuestion(question: Omit<DiagnosticQuestion, 'id' | 'source' | 'createdAt'>): DiagnosticQuestion;
/** 批量添加自定义问题 */
export declare function addCustomQuestions(questions: Omit<DiagnosticQuestion, 'id' | 'source' | 'createdAt'>[]): DiagnosticQuestion[];
/** 删除自定义问题 */
export declare function removeCustomQuestion(id: string): boolean;
/** 获取问题总数（内置 + 自定义） */
export declare function getQuestionCount(): {
    builtin: number;
    custom: number;
};
/** 清除所有自定义问题（测试用） */
export declare function clearCustomQuestions(): void;
/** 获取种子问题列表（只读，供 FDE 参考） */
export declare function getSeedQuestions(): readonly DiagnosticQuestion[];
/** 为特定角色生成诊断问卷 */
export declare function generateQuestionnaire(targetRole: TargetRole, phase?: DiagnosticPhase, maxQuestions?: number): DiagnosticQuestion[];
